import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007L;

    static class Matrix {
        int size;
        long[][] mat;

        Matrix(int size) {
            this.size = size;
            this.mat = new long[size + 1][size + 1];
        }

        Matrix multiply(Matrix B) {
            Matrix C = new Matrix(this.size);
            for (int i = 0; i <= size; ++i) {
                for (int j = 0; j <= size; ++j) {
                    C.mat[i][j] = 0;
                    for (int k = 0; k <= size; ++k) {
                        C.mat[i][j] = (C.mat[i][j] + this.mat[i][k] * B.mat[k][j]) % MOD;
                    }
                }
            }
            return C;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long N = sc.nextLong();
        long K = sc.nextLong();

        int[] digits = new int[70];
        int count_digits = 0;
        while (N != 0) {
            digits[count_digits++] = (int)(N % K);
            N /= K;
        }

        @SuppressWarnings("unchecked")
        Matrix[][] A = new Matrix[(int) (64)][(int) K];
        @SuppressWarnings("unchecked")
        Matrix[][] prefixSum = new Matrix[(int) (64)][(int) K];
        @SuppressWarnings("unchecked")
        Matrix[][] suffix = new Matrix[(int) (64)][(int) K];

        for (int i = 0; i < K; ++i) {
            for (int j = 0; j <= K; ++j) {
                A[0][i] = new Matrix((int) K);
                for (int x = 0; x <= K; ++x) {
                    A[0][i].mat[x][x] = 1;
                }
                A[0][i].mat[j][j] = 1;
                A[0][i].mat[j][(int) i] = 1;
            }
        }

        // Initialize prefixSum[0][0]
        prefixSum[0][0] = new Matrix((int) K);
        for (int j = 0; j <= K; ++j) {
            prefixSum[0][0].mat[j][j] = 1;
        }

        // Initialize suffix[0][K-1]
        suffix[0][(int) (K - 1)] = new Matrix((int) K);
        for (int j = 0; j <= K; ++j) {
            suffix[0][(int) (K - 1)].mat[j][j] = 1;
        }

        for (int i = 1; i < K; ++i) {
            prefixSum[0][i] = prefixSum[0][i - 1].multiply(A[0][i]);
        }

        for (int i = (int) (K - 2); i >= 0; --i) {
            suffix[0][i] = A[0][i].multiply(suffix[0][i + 1]);
        }

        for (int i = 1; i < count_digits; ++i) {
            A[i][0] = suffix[i - 1][0];
            for (int j = 1; j < K; ++j) {
                A[i][j] = suffix[i - 1][j].multiply(prefixSum[i - 1][j - 1]);
            }

            prefixSum[i][0] = A[i][0];
            for (int j = 1; j < K; ++j) {
                prefixSum[i][j] = prefixSum[i][j - 1].multiply(A[i][j]);
            }

            for (int j = (int) (K - 2); j >= 0; --j) {
                suffix[i][j] = A[i][j].multiply(suffix[i][j + 1]);
            }
        }

        Matrix result = new Matrix((int) K);
        result.mat[0][(int) K] = 1;
        result.size = (int) K;

        result = result.multiply(prefixSum[count_digits - 1][digits[count_digits - 1] - 1]);

        int last = digits[count_digits - 1];
        for (int i = count_digits - 2; i >= 0; --i) {
            for (int j = 0; j < digits[i]; ++j) {
                result = result.multiply(A[i][(j + last) % (int) K]);
            }
            last += digits[i];
        }

        long total = 0;
        for (int i = 0; i <= K; ++i) {
            total += result.mat[0][i];
        }

        System.out.println(total % MOD);
        sc.close();
    }
}
